{"implementation": "def solve(case):
    # Validate required fields at top level
    if 'threshold' not in case:
        raise ValueError("Missing 'threshold' in case")
    if 'calls' not in case:
        raise ValueError("Missing 'calls' in case")
    if not isinstance(case['calls'], list):
        raise ValueError("'calls' must be a list")

    threshold = case['threshold']
    if not isinstance(threshold, (int, float)):
        raise ValueError("'threshold' must be a number")

    calls = case['calls']
    required_call_keys = {'call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable'}

    diagnostics = []
    accepted_call_ids = []

    for i, call in enumerate(calls):
        # Validate call structure
        if not isinstance(call, dict):
            raise ValueError(f"Call at index {i} is not a dict")
        missing = required_call_keys - set(call.keys())
        if missing:
            raise ValueError(f"Call at index {i} missing keys: {missing}")

        call_id = call['call_id']
        loss_without = call['loss_without_call']
        loss_with = call['loss_with_call']
        prediction_tokens = call['prediction_tokens']
        parseable = call['parseable']

        # Validate types
        if not isinstance(call_id, str):
            raise ValueError(f"call_id at index {i} must be a string")
        if not isinstance(loss_without, (int, float)):
            raise ValueError(f"loss_without_call at index {i} must be a number")
        if not isinstance(loss_with, (int, float)):
            raise ValueError(f"loss_with_call at index {i} must be a number")
        if not isinstance(prediction_tokens, int) or prediction_tokens <= 0:
            raise ValueError(f"prediction_tokens at index {i} must be a positive integer")
        if not isinstance(parseable, bool):
            raise ValueError(f"parseable at index {i} must be a boolean")

        # Compute gain and normalize
        gain = loss_without - loss_with
        normalized_gain = gain / prediction_tokens

        # Determine acceptance
        accepted = parseable and normalized_gain >= threshold

        # Build diagnostics entry (preserve order)
        diagnostics.append({
            'call_id': call_id,
            'accepted': accepted,
            'normalized_gain': normalized_gain
        })

        if accepted:
            accepted_call_ids.append(call_id)

    return {
        'accepted_call_ids': accepted_call_ids,
        'diagnostics': diagnostics
    }"}
}
